function sheetBase(){$('sheetBody').innerHTML=`<div class="stitle">${tr('find')}</div><div class="actions"><button data-photo>${tr('photo')}</button><button data-qr>${tr('qr')}</button><button data-search>${tr('search')}</button><button data-voice>${tr('voice')}</button></div>`;openSheet();bind()}
function openSheet(){$('sheetMask').classList.add('on');$('sheetWrap').classList.add('on')}function hideSheet(){$('sheetMask').classList.remove('on');$('sheetWrap').classList.remove('on')}
function searchMode(q=''){$('sheetBody').innerHTML=`<div class="stitle">${tr('search')}</div><div class="actions"><button data-photo>${tr('photo')}</button><button data-qr>${tr('qr')}</button><button data-search>${tr('search')}</button><button data-voice>${tr('voice')}</button></div><div class="searchline"><input id="q" value="${q}" placeholder="${S.lang==='ru'?'Иванов / дисплей 15 Pro / 12541':'Ivanov / display 15 Pro / 12541'}"><button data-photo>Фото</button><button data-voice>Голос</button></div><div id="res"></div>`;openSheet();draw(q);$('q').addEventListener('input',e=>draw(e.target.value));bind()}
function draw(q=''){let r=$('res');if(!r)return;q=q.toLowerCase().trim();if(!q){r.innerHTML=`<div class="result" data-fill="иванов"><b>Иванов</b><span>${S.lang==='ru'?'Клиент':'Client'}</span></div><div class="result" data-fill="дисплей 15 pro"><b>дисплей 15 Pro</b><span>${S.lang==='ru'?'Запчасть':'Part'}</span></div><div class="result" data-fill="12541"><b>12541</b><span>${S.lang==='ru'?'Заказ':'Order'}</span></div>`}else if(q.includes('иван'))r.innerHTML=`<div class="result" data-clientres><b>${S.lang==='ru'?'Иванов Сергей':'Ivanov Sergey'}</b><span>+7 999 123-45-67 · ${tr('start')}</span></div>`;else if(q.includes('дисп')||q.includes('15 pro'))r.innerHTML=`<div class="result" data-partres="Дисплей iPhone 15 Pro|6 450 ₽ · Supplier B"><b>${S.lang==='ru'?'Дисплей iPhone 15 Pro':'iPhone 15 Pro Display'}</b><span>${S.lang==='ru'?'Склад / поставщик / цена':'Inventory / supplier / price'}</span></div><div class="result" data-partres="Original Pull iPhone 15 Pro|8 200 ₽ · Supplier A"><b>Original Pull iPhone 15 Pro</b><span>${S.lang==='ru'?'Склад / поставщик / цена':'Inventory / supplier / price'}</span></div>`;else if(q.includes('12541'))r.innerHTML=`<div class="result" data-orderres><b>№12541 · ${S.lang==='ru'?'Иванов Сергей':'Ivanov Sergey'}</b><span>${S.lang==='ru'?'Открыть заказ':'Open order'}</span></div>`;else r.innerHTML=`<div class="result"><b>${S.lang==='ru'?'Нет точного совпадения':'No exact match'}</b></div>`;bind()}
function photo(){$('sheetBody').innerHTML=`<div class="stitle">${tr('photo')}</div><div class="row"><b>${S.lang==='ru'?'Камера (симуляция)':'Camera (simulation)'}</b><span>${S.lang==='ru'?'Распознано: iPhone 15 Pro, разбит экран':'Detected: iPhone 15 Pro, broken screen'}</span></div><button class="primary" data-fromphoto>${tr('start')}</button>`;openSheet();bind()}
function qr(){$('sheetBody').innerHTML=`<div class="stitle">${tr('qr')}</div><div class="row"><b>${S.lang==='ru'?'Гарантия':'Warranty'}</b><span>${S.lang==='ru'?'Активна до 18.05.2025':'Active until 18.05.2025'}</span></div><div class="row"><b>${S.lang==='ru'?'Статус ремонта':'Repair status'}</b><span>№45678 · ${S.lang==='ru'?'В ремонте':'In repair'}</span></div><button class="primary" data-fromqr>${tr('start')}</button>`;openSheet();bind()}
function voice(){$('sheetBody').innerHTML=`<div class="stitle">${tr('voice')}</div><div class="row"><b>${S.lang==='ru'?'Голосовая команда (симуляция)':'Voice command (simulation)'}</b><span>${S.lang==='ru'?'«Клиент пришёл, телефон 79991234567, iPhone 14 Pro, не включается»':'"Client arrived, phone 79991234567, iPhone 14 Pro, does not turn on"'}</span></div><button class="primary" data-fromvoice>${S.lang==='ru'?'Применить к ремонту':'Apply to repair'}</button>`;openSheet();bind()}
function toast(x){let t=$('toast');t.textContent=x;t.classList.add('on');clearTimeout(window.tt);window.tt=setTimeout(()=>t.classList.remove('on'),1500)}
